import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * CEM analyzer plugin moving the custom attributes (classes extending `CustomAttribute`) out of the
 * "elements" contributions of the IDE files generated by the other plugins:
 *
 * - `web-types.json` (JetBrains): `contributions.html.elements` -> `contributions.html.attributes`;
 * - `vscode.html-custom-data.json` (VS Code): `tags` -> `globalAttributes`.
 *
 * This way, IDEs autocomplete custom attributes on any element (e.g. `<a esds-button>`) instead of
 * exposing them as custom element tags.
 *
 * NOTE: this plugin must be registered **after** the plugins generating those files (they write
 * them during their own `packageLinkPhase`, which the analyzer runs in registration order).
 */

/* OPTIONS */

/** Options of the `customAttributesIdePlugin` CEM analyzer plugin. */
export interface CustomAttributesIdePluginOptions {
  /**
   * Directory containing the IDE files generated by the other CEM plugins.
   *
   * @default './dist'
   */
  readonly outdir?: string;
}

/* CEM SUBSET */

/** Minimal subset of the Custom Elements Manifest needed to detect custom attribute declarations. */
interface CustomElementsManifest {
  readonly modules?: readonly CemModule[];
}

interface CemModule {
  readonly declarations?: readonly CemDeclaration[];
}

interface CemDeclaration {
  readonly tagName?: string;
  readonly superclass?: CemSuperclass;
}

interface CemSuperclass {
  readonly name?: string;
  readonly module?: string;
}

/* WEB-TYPES SUBSET */

/**
 * Minimal subset of the Web-Types schema touched by this plugin. Entries may carry arbitrary
 * extra fields (js, events, slots, ...), which are preserved as-is.
 */
export interface WebTypesDocument {
  contributions?: {
    html?: {
      elements?: DocumentedElement[];
      attributes?: WebTypesAttribute[];
    };
  };
}

/** Shape shared by Web-Types element contributions and VS Code tag contributions. */
export interface DocumentedElement {
  name?: string;
  description?: string;
  attributes?: DocumentedAttribute[];
  [key: string]: unknown;
}

export interface WebTypesAttribute {
  name?: string;
  description?: string;
  value?: {
    kind: 'no-value' | 'plain' | 'expression';
  };
  [key: string]: unknown;
}

export interface DocumentedAttribute {
  name?: string;
  description?: string;
  [key: string]: unknown;
}

/* VS CODE SUBSET */

/** Minimal subset of the VS Code `html.html-data` schema touched by this plugin. */
export interface VsCodeCustomDataDocument {
  tags?: DocumentedElement[];
  globalAttributes?: VsCodeGlobalAttribute[];
  [key: string]: unknown;
}

export interface VsCodeGlobalAttribute {
  name?: string;
  description?: string;
  [key: string]: unknown;
}

/* PLUGIN */

/** Plugin expected by the CEM analyzer. */
interface CemAnalyzerPlugin {
  readonly name: string;
  packageLinkPhase(context: { readonly customElementsManifest: CustomElementsManifest }): void;
}

const PLUGIN_NAME = 'custom-attributes-ide-contributions';
const DEFAULT_OUTDIR = './dist';

const WEB_TYPES_FILE_NAME = 'web-types.json';
const VS_CODE_CUSTOM_DATA_FILE_NAME = 'vscode.html-custom-data.json';

const CUSTOM_ATTRIBUTE_SUPERCLASS_NAME = 'CustomAttribute';
const CUSTOM_ATTRIBUTE_MODULE_HINT = 'custom-attribute';

const MARKDOWN_HORIZONTAL_RULE = '\n---';

/**
 * Creates the CEM analyzer plugin moving custom attributes to the "attributes" contributions of
 * the generated IDE files.
 *
 * @param options - Plugin options.
 * @returns The CEM analyzer plugin.
 */
export function customAttributesIdePlugin(
  options: CustomAttributesIdePluginOptions = {},
): CemAnalyzerPlugin {
  const outdir = options.outdir ?? DEFAULT_OUTDIR;

  return {
    name: PLUGIN_NAME,
    packageLinkPhase({ customElementsManifest }): void {
      const tagNames = collectCustomAttributeTagNames(customElementsManifest);

      if (tagNames.size === 0) {
        return;
      }

      rewriteWebTypesFile(join(outdir, WEB_TYPES_FILE_NAME), tagNames);
      rewriteVsCodeCustomDataFile(join(outdir, VS_CODE_CUSTOM_DATA_FILE_NAME), tagNames);
    },
  };
}

/* TAG NAMES COLLECTION */

/**
 * Collects the tag names of the manifest declarations describing a custom attribute (a class
 * extending `CustomAttribute`) instead of a real custom element.
 *
 * @param manifest - Custom Elements Manifest.
 * @returns The tag names of the custom attributes.
 */
export function collectCustomAttributeTagNames(manifest: CustomElementsManifest): Set<string> {
  const tagNames = new Set<string>();

  for (const module of manifest.modules ?? []) {
    for (const declaration of module.declarations ?? []) {
      if (declaration.tagName === undefined || !isCustomAttributeDeclaration(declaration)) {
        continue;
      }

      tagNames.add(declaration.tagName);
    }
  }

  return tagNames;
}

function isCustomAttributeDeclaration(declaration: CemDeclaration): boolean {
  const superclass = declaration.superclass;

  return (
    superclass !== undefined &&
    (superclass.name === CUSTOM_ATTRIBUTE_SUPERCLASS_NAME ||
      (superclass.module ?? '').includes(CUSTOM_ATTRIBUTE_MODULE_HINT))
  );
}

/* WEB-TYPES TRANSFORMATION */

/**
 * Moves the Web-Types element contributions matching `tagNames` to the
 * `contributions.html.attributes` section.
 *
 * @param document - Parsed `web-types.json` content (mutated in place).
 * @param tagNames - Tag names of the custom attributes to move.
 * @returns Whether the document was modified.
 */
export function moveWebTypesElementsToAttributes(
  document: WebTypesDocument,
  tagNames: ReadonlySet<string>,
): boolean {
  const html = document.contributions?.html;

  if (html?.elements === undefined) {
    return false;
  }

  const remainingElements: DocumentedElement[] = [];
  const attributes = html.attributes ?? [];
  let hasMoved = false;

  for (const element of html.elements) {
    if (element.name !== undefined && tagNames.has(element.name)) {
      attributes.push(toWebTypesAttribute(element));
      hasMoved = true;
    } else {
      remainingElements.push(element);
    }
  }

  if (!hasMoved) {
    return false;
  }

  html.elements = remainingElements;
  html.attributes = attributes;

  return true;
}

function toWebTypesAttribute(element: DocumentedElement): WebTypesAttribute {
  return {
    name: element.name,
    description: buildAttributeDescription(element),
    // Custom attributes are presence flags: they are used without value (like the native `disabled`).
    value: { kind: 'no-value' },
  };
}

function rewriteWebTypesFile(filePath: string, tagNames: ReadonlySet<string>): void {
  if (!existsSync(filePath)) {
    return;
  }

  const document = JSON.parse(readFileSync(filePath, 'utf8')) as WebTypesDocument;

  if (moveWebTypesElementsToAttributes(document, tagNames)) {
    writeFileSync(filePath, `${JSON.stringify(document, null, 2)}\n`);
    console.log(
      `[${PLUGIN_NAME}] - Moved custom attributes to attribute contributions in "${WEB_TYPES_FILE_NAME}".`,
    );
  }
}

/* VS CODE TRANSFORMATION */

/**
 * Moves the VS Code tag contributions matching `tagNames` to the `globalAttributes` section.
 *
 * @param document - Parsed `vscode.html-custom-data.json` content (mutated in place).
 * @param tagNames - Tag names of the custom attributes to move.
 * @returns Whether the document was modified.
 */
export function moveVsCodeTagsToGlobalAttributes(
  document: VsCodeCustomDataDocument,
  tagNames: ReadonlySet<string>,
): boolean {
  if (document.tags === undefined) {
    return false;
  }

  const remainingTags: DocumentedElement[] = [];
  const globalAttributes = document.globalAttributes ?? [];
  let hasMoved = false;

  for (const tag of document.tags) {
    if (tag.name !== undefined && tagNames.has(tag.name)) {
      globalAttributes.push(toVsCodeGlobalAttribute(tag));
      hasMoved = true;
    } else {
      remainingTags.push(tag);
    }
  }

  if (!hasMoved) {
    return false;
  }

  document.tags = remainingTags;
  document.globalAttributes = globalAttributes;

  return true;
}

function toVsCodeGlobalAttribute(tag: DocumentedElement): VsCodeGlobalAttribute {
  return {
    name: tag.name,
    description: buildAttributeDescription(tag),
  };
}

function rewriteVsCodeCustomDataFile(filePath: string, tagNames: ReadonlySet<string>): void {
  if (!existsSync(filePath)) {
    return;
  }

  const document = JSON.parse(readFileSync(filePath, 'utf8')) as VsCodeCustomDataDocument;

  if (moveVsCodeTagsToGlobalAttributes(document, tagNames)) {
    writeFileSync(filePath, `${JSON.stringify(document, null, 2)}\n`);
    console.log(
      `[${PLUGIN_NAME}] - Moved custom attributes to global attributes in "${VS_CODE_CUSTOM_DATA_FILE_NAME}".`,
    );
  }
}

/* DESCRIPTION */

/**
 * Builds the description of a custom attribute contribution from its former element contribution:
 *
 * - drops the trailing markdown horizontal rule appended by the IDE plugins when no auto-generated
 *   section follows it;
 * - folds the documented host attributes (e.g. `disabled` and `loading` for `esds-button`) into the
 *   description, as neither schema supports per-attribute nested documentation.
 *
 * @param source - Element/tag contribution to convert.
 * @returns The description of the custom attribute contribution.
 */
export function buildAttributeDescription(source: {
  description?: string;
  attributes?: readonly DocumentedAttribute[];
}): string {
  let description = (source.description ?? '').trimEnd();

  if (description.endsWith(MARKDOWN_HORIZONTAL_RULE)) {
    description = description.slice(0, -MARKDOWN_HORIZONTAL_RULE.length).trimEnd();
  }

  const documentedAttributes = (source.attributes ?? []).filter(hasNonEmptyName);

  if (documentedAttributes.length === 0) {
    return description;
  }

  const lines = documentedAttributes.map(
    (attribute) =>
      `- **${attribute.name}**${attribute.description ? ` - ${attribute.description}` : ''}`,
  );

  return description.length > 0 ? `${description}\n\n${lines.join('\n')}` : lines.join('\n');
}

function hasNonEmptyName(
  attribute: DocumentedAttribute,
): attribute is DocumentedAttribute & { name: string } {
  return typeof attribute.name === 'string' && attribute.name.length > 0;
}
